import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

function uniqueEmail(): string {
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@vendor-intake.com`;
}

test.describe("upload vendor documents", () => {
  test("rejects an empty file with empty_file", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const vendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc vendor"), category: "services", contact_email: uniqueEmail() },
    });
    expect(vendor.status(), await vendor.text()).toBe(201);
    const { id } = (await vendor.json()) as { id: string };

    const res = await member.post(`/api/vendors/${id}/documents`, {
      multipart: { kind: "w9", file: { name: "empty.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(0) } },
    });

    expect(res.status(), await res.text()).toBe(422);
    expect((await res.json()).error.code).toBe("empty_file");
  });

  test("rejects a file over 10 MiB with file_too_large", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const vendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc vendor"), category: "services", contact_email: uniqueEmail() },
    });
    expect(vendor.status(), await vendor.text()).toBe(201);
    const { id } = (await vendor.json()) as { id: string };

    const res = await member.post(`/api/vendors/${id}/documents`, {
      multipart: { kind: "w9", file: { name: "big.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(TEN_MIB + 1) } },
    });

    expect(res.status(), await res.text()).toBe(413);
    expect((await res.json()).error.code).toBe("file_too_large");
  });

  test("rejects an .exe file with unsupported_type", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const vendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc vendor"), category: "services", contact_email: uniqueEmail() },
    });
    expect(vendor.status(), await vendor.text()).toBe(201);
    const { id } = (await vendor.json()) as { id: string };

    const res = await member.post(`/api/vendors/${id}/documents`, {
      multipart: { kind: "w9", file: { name: "setup.exe", mimeType: "application/x-msdownload", buffer: Buffer.from("MZ") } },
    });

    expect(res.status(), await res.text()).toBe(415);
    expect((await res.json()).error.code).toBe("unsupported_type");
  });

  test("rejects an unknown kind with validation_error", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const vendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc vendor"), category: "services", contact_email: uniqueEmail() },
    });
    expect(vendor.status(), await vendor.text()).toBe(201);
    const { id } = (await vendor.json()) as { id: string };

    const res = await member.post(`/api/vendors/${id}/documents`, {
      multipart: { kind: "passport", file: { name: "notes.txt", mimeType: "text/plain", buffer: Buffer.from("hello") } },
    });

    expect(res.status(), await res.text()).toBe(422);
    expect((await res.json()).error.code).toBe("validation_error");
  });
});
